package com.ruoyi.majorpilot.integration.ai;
import com.fasterxml.jackson.databind.*;
import com.ruoyi.majorpilot.content.*;
import com.ruoyi.majorpilot.experience.HintProvider;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.Flow;
import java.nio.ByteBuffer;
import java.io.ByteArrayOutputStream;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class ExperienceFollowUpTest {
    private static final ObjectMapper JSON=new ObjectMapper();private static final String ID="01JA1000000000000000000001";
    private byte[] envelope(String output)throws Exception{return JSON.writeValueAsBytes(Map.of("choices",List.of(Map.of("finish_reason","stop","message",Map.of("content",output)))));}
    private TaskContentProvider content(){var repository=new TaskContentRepository(JSON);var bundle=repository.get("ai-support/1.0.0/manifest.json");var content=mock(TaskContentProvider.class);when(content.pinnedForPreview(ID)).thenReturn(new TaskContent.Version(1,ID,"MAJOR","AI",null,"1.0.0",bundle.manifestSha256(),bundle.manifest()));return content;}
    private HintProvider.Context context(){var safe=JSON.createObjectNode().put("continueSimilarWork","UNSURE").put("nextWorkStyle","MODEL_ITERATION").put("reflectionNote","private free text must not leave").put("email","no-forward@example.invalid");safe.putArray("interestingStepKeys").add("a3-errors");safe.putArray("difficultySources").add("KNOWLEDGE");return new HintProvider.Context(ID,"1.0.0","reflection",1,"reflection-follow-up-v1",safe,"",false,"REVIEW_PREVIEW");}
    @Test void actualBusinessWireIsWhitelistedAndReportsRealAttemptCount()throws Exception {AtomicInteger calls=new AtomicInteger();var gateway=new FollowUpBailianGateway("synthetic-test-key",BailianAiGateway.DEFAULT_BASE_URL,BailianAiGateway.DEFAULT_MODEL,(http,timeout)->{calls.incrementAndGet();try{JsonNode body=JSON.readTree(body(http));assertEquals(512,body.path("max_tokens").asInt());assertFalse(body.path("enable_thinking").asBoolean());assertEquals("json_object",body.at("/response_format/type").asText());JsonNode context=JSON.readTree(body.at("/messages/1/content").asText());assertEquals(4,context.path("reflectionChoices").size());assertFalse(context.toString().contains("private free text"));assertFalse(context.toString().contains("email"));assertFalse(context.toString().contains("goldLabel"));return new BailianAiGateway.TransportResponse(200,envelope("{\"question\":\"你希望下次用哪一种具体尝试来进一步验证兴趣？\"}"));}catch(Exception e){throw new AssertionError(e);}},30000,ms->{});var result=new ExperienceHintProvider(content(),null,gateway).followUp(context());assertEquals("SUCCEEDED",result.status());assertEquals(1,calls.get());assertEquals(1,result.telemetry().httpAttempts());assertEquals(0,result.telemetry().repairAttempts());assertEquals(4,result.telemetry().inputFieldKeys().size());}
    @Test void disabledModeMakesNoQuestionAndRemainsSkippable(){var result=new ExperienceHintProvider(content(),new MockEnvironment().withProperty("MAJORPILOT_AI_MODE","bailian").withProperty("BAILIAN_API_KEY","synthetic-test-key")).followUp(context());assertEquals("FAILED",result.status());assertNull(result.response());assertEquals(0,result.telemetry().httpAttempts());assertEquals("AI_DISABLED",result.telemetry().errorCode());}
    @Test void malformedOutputGetsOneRepairAndNoFabricatedFallbackQuestion()throws Exception {AtomicInteger calls=new AtomicInteger();byte[] invalid=envelope("{\"question\":\"你的录取概率很高？\"}");var gateway=new FollowUpBailianGateway("synthetic-test-key",BailianAiGateway.DEFAULT_BASE_URL,BailianAiGateway.DEFAULT_MODEL,(h,t)->{calls.incrementAndGet();return new BailianAiGateway.TransportResponse(200,invalid);},30000,ms->{});var result=new ExperienceHintProvider(content(),null,gateway).followUp(context());assertEquals("FAILED",result.status());assertNull(result.response());assertEquals(2,calls.get());assertEquals(1,result.telemetry().repairAttempts());assertEquals("INVALID_OUTPUT",result.telemetry().errorCode());}
    @Test void transientRetryIsBoundedAndDoesNotRepeatARepair()throws Exception {for(boolean malformedFirst:List.of(false,true)){AtomicInteger calls=new AtomicInteger();byte[] malformed=envelope("{}");var gateway=new FollowUpBailianGateway("synthetic-test-key",BailianAiGateway.DEFAULT_BASE_URL,BailianAiGateway.DEFAULT_MODEL,(h,t)->{int attempt=calls.incrementAndGet();if(malformedFirst&&attempt==1)return new BailianAiGateway.TransportResponse(200,malformed);throw new AiFailure(AiFailure.Code.RATE_LIMITED);},30000,ms->{});var result=new ExperienceHintProvider(content(),null,gateway).followUp(context());assertEquals("FAILED",result.status());assertEquals(2,calls.get());assertEquals(malformedFirst?1:0,result.telemetry().repairAttempts());assertEquals("RATE_LIMITED",result.telemetry().errorCode());}}
    @Test void extraOutputFieldsLinksMultipleQuestionsAndForeignContextFailClosed()throws Exception {for(String out:List.of("{\"question\":\"a\",\"score\":99}","{\"question\":\"https://example.invalid\"}","{\"question\":\"感受如何？为什么？\"}"))assertThrows(AiFailure.class,()->FollowUpBailianGateway.validateResult(JSON.readTree(out)));var gateway=new FollowUpBailianGateway("synthetic-test-key",BailianAiGateway.DEFAULT_BASE_URL,BailianAiGateway.DEFAULT_MODEL,(h,t)->{fail("Invalid context must not call transport");return null;},30000,ms->{});assertThrows(AiFailure.class,()->gateway.followUp(new FollowUpBailianGateway.Request(ID,"测试",JSON.createObjectNode().put("email","secret@example.invalid"))));}
    private static byte[] body(java.net.http.HttpRequest request){ByteArrayOutputStream out=new ByteArrayOutputStream();request.bodyPublisher().orElseThrow().subscribe(new Flow.Subscriber<ByteBuffer>(){public void onSubscribe(Flow.Subscription s){s.request(Long.MAX_VALUE);}public void onNext(ByteBuffer buffer){byte[] bytes=new byte[buffer.remaining()];buffer.get(bytes);out.writeBytes(bytes);}public void onError(Throwable error){throw new AssertionError(error);}public void onComplete(){}});return out.toByteArray();}
}
